def test_index(r, idx):
    try:
        r.recvuntil(b"??", timeout=2)
        r.sendline(str(idx).encode())
        response = r.recvline(timeout=2)
        if b"0x" in response:
            return response.strip()
        return response
    except:
        return b"Timeout or error"

def run_single_test(idx):
    try:
        r = remote("pwn.chal.csaw.io", 5000, timeout=5)
        val = test_index(r, idx)
        r.close()
        return val
    except:
        return b"Connection failed"

def main():
